from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

items = [
    {"id": 1, "name": "Microscope", "quantity": 4},
]


class ItemCreate(BaseModel):
    name: str
    quantity: int = 1


class Item(BaseModel):
    id: int
    name: str
    quantity: int


@app.get("/items/{item_id}")
def read_item(item_id: int) -> Item:
    # TODO: return the requested item as a typed Item
    return items[0]


@app.post("/items")
def create_item(payload: ItemCreate) -> Item:
    item = Item(id=len(items) + 1, name=payload.name, quantity=payload.quantity)
    items.append(item.model_dump())
    return item
